mapper.select:
SELECT location_id, latitude, longitude, location_name, address, location_status, created_at, updated_at
  FROM tb_location
 WHERE latitude = #{latitude}
   AND longitude = #{longitude}
   AND location_name = #{locationName}

SELECT * FROM ( SELECT GROUP_CONCAT(location_id) AS locationIds, NULL AS locationId, NULL AS locationName, latitude, longitude, COUNT(*) AS count, NULL AS momentCount FROM tb_location WHERE location_status = 'UNCHANGED' AND latitude BETWEEN #{latitudeMin} AND #{latitudeMax} AND longitude BETWEEN #{longitudeMin} AND #{longitudeMax} GROUP BY latitude, longitude HAVING COUNT(*) > 1
UNION
SELECT CAST(location_id AS CHAR) AS locationIds, location_id AS locationId, location_name AS locationName, latitude, longitude, 1 AS count, (SELECT COUNT(*) FROM tb_moment m WHERE m.location_id = l.location_id AND m.moment_status = true) AS momentCount FROM tb_location l WHERE location_status = 'UNCHANGED' AND latitude BETWEEN #{latitudeMin} AND #{latitudeMax} AND longitude BETWEEN #{longitudeMin} AND #{longitudeMax} GROUP BY latitude, longitude, location_id HAVING COUNT(*) = 1 ) AS clustered LIMIT #{limit}
